# F_mut: the bin-scoring heuristic — the ONLY thing evolution changes. Given the
# arriving `item` size and `bins` (a numpy array of the remaining capacities of
# the bins that can hold it), return a score per bin; the item is placed in the
# highest-scoring bin. A better heuristic packs into fewer bins.
def priority(item, bins):
    """Adaptive hybrid: blend best-fit and worst-fit based on item size relative to capacity."""
    slack = bins - item
    # For large items (>60% capacity), strongly prefer tight fit to avoid waste
    # For small items, prefer keeping large bins open by using bins with similar remaining capacity
    if item > 60:
        return -slack * 2.0  # Aggressive best-fit for large items
    elif item > 30:
        # Medium items: balance between tight fit and preserving large bins
        return -slack + 0.3 * (bins / 100.0)
    else:
        # Small items: prefer bins that are moderately full to save large bins
        return -(slack ** 1.5) + 0.1 * (100 - bins)
